export type OrgRole = "member" | "billing" | "admin" | "owner";

export const ROLE_RANK: Record<OrgRole, number> = {
  member: 1,
  billing: 2,
  admin: 3,
  owner: 4,
};

export interface OrgMember {
  orgId: string;
  userId: string;
  role: OrgRole;
}

export interface MemberRepo {
  get(orgId: string, userId: string): Promise<OrgMember | null>;
  updateRole(orgId: string, userId: string, role: OrgRole): Promise<void>;
  countOwners(orgId: string): Promise<number>;
}

export interface AuditLog {
  record(event: {
    orgId: string;
    actorId: string;
    action: string;
    targetId: string;
    detail: Record<string, unknown>;
  }): Promise<void>;
}

export class ForbiddenError extends Error {
  constructor(public readonly code: string) {
    super(code);
  }
}

export class NotFoundError extends Error {}

export class ConflictError extends Error {
  constructor(public readonly code: string) {
    super(code);
  }
}

import {
  AuditLog,
  ConflictError,
  ForbiddenError,
  MemberRepo,
  NotFoundError,
  OrgRole,
  ROLE_RANK,
} from "./model";

export class RoleAssignmentService {
  constructor(private readonly members: MemberRepo, private readonly audit: AuditLog) {}

  async changeRole(orgId: string, actorId: string, targetUserId: string, newRole: OrgRole): Promise<void> {
    const actor = await this.members.get(orgId, actorId);
    if (!actor) {
      throw new NotFoundError("organization not found");
    }
    if (ROLE_RANK[actor.role] < ROLE_RANK.admin) {
      throw new ForbiddenError("role_management_requires_admin");
    }

    const target = await this.members.get(orgId, targetUserId);
    if (!target) {
      throw new NotFoundError("member not found");
    }
    if (target.role === newRole) {
      return;
    }

    if (ROLE_RANK[actor.role] < ROLE_RANK[target.role]) {
      throw new ForbiddenError("cannot_modify_higher_role");
    }

    if (target.role === "owner" && newRole !== "owner") {
      const owners = await this.members.countOwners(orgId);
      if (owners <= 1) {
        throw new ConflictError("last_owner");
      }
    }

    await this.members.updateRole(orgId, targetUserId, newRole);
    await this.audit.record({
      orgId,
      actorId,
      action: "member.role_changed",
      targetId: targetUserId,
      detail: { from: target.role, to: newRole },
    });
  }
}

import { Router, Request, Response, NextFunction } from "express";
import { RoleAssignmentService } from "./roleAssignment";
import { ConflictError, ForbiddenError, NotFoundError, OrgRole, ROLE_RANK } from "./model";

interface AuthedRequest extends Request {
  session?: { userId: string };
}

export function memberRoutes(service: RoleAssignmentService): Router {
  const router = Router();

  router.put("/orgs/:orgId/members/:userId/role", async (req: AuthedRequest, res: Response, next: NextFunction) => {
    if (!req.session) {
      res.status(401).json({ error: "unauthenticated" });
      return;
    }
    const role = req.body?.role as OrgRole;
    if (!(role in ROLE_RANK)) {
      res.status(400).json({ error: "invalid_role" });
      return;
    }
    try {
      await service.changeRole(req.params.orgId, req.session.userId, req.params.userId, role);
      res.status(204).end();
    } catch (err) {
      if (err instanceof NotFoundError) {
        res.status(404).json({ error: "not_found" });
      } else if (err instanceof ForbiddenError) {
        res.status(403).json({ error: err.code });
      } else if (err instanceof ConflictError) {
        res.status(409).json({ error: err.code });
      } else {
        next(err);
      }
    }
  });

  return router;
}
